const r = $('Find SLA Breaches').first().json.report || {};
const breaches = Array.isArray(r.breaches) ? r.breaches : [];
const total = r.total_breaches || 0;
const sla = r.sla_table || { urgent_days: 2, high_days: 5, medium_days: 14, low_days: 30 };

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }
const sevColor = { low: '#888', medium: '#3b82f6', high: '#e67e22', urgent: '#c00' };

const rows = breaches.map(b => {
  const bgColor = b.severity === 'urgent' ? '#fee' : (b.days_overdue > 7 ? '#fff8e0' : '#fff');
  return `<tr style="background:${bgColor}">
    <td><span style="background:${sevColor[b.severity] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:bold">${esc(b.severity)}</span></td>
    <td>${esc(b.project_name)}</td>
    <td>${esc(b.category || '-')}</td>
    <td>${esc(b.responsible_trade || '-')}</td>
    <td>${esc(b.assigned_to || '-')}</td>
    <td>${dateShort(b.assigned_at)}</td>
    <td style="text-align:right">${b.sla_days}d</td>
    <td style="text-align:right;color:#c00;font-weight:600">${b.days_since_assigned}d (+${b.days_overdue})</td>
    <td style="font-size:12px;color:#555">${esc(b.desc_preview)}...</td>
  </tr>`;
}).join('');

const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:920px">
<h2>Aftercare SLA breach (${total} incidentes)</h2>
<p style="font-size:13px;color:#555">Incidentes con status <code>assigned</code> o <code>in_progress</code> que llevan asignados mas dias del SLA por severidad. El colaborador o gremio asignado no esta cumpliendo el plazo. Considerar escalar (status='escalated') o reasignar.</p>
<p style="font-size:12px;color:#666;margin-top:6px"><b>SLA aplicado</b>: urgent=${sla.urgent_days}d · high=${sla.high_days}d · medium=${sla.medium_days}d · low=${sla.low_days}d (desde assigned_at)</p>
<table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:12px"><thead><tr style="background:#f0f0f3"><th align="left">sev</th><th align="left">proyecto</th><th align="left">cat</th><th align="left">gremio</th><th align="left">asignado a</th><th align="left">desde</th><th align="right">SLA</th><th align="right">dias (overdue)</th><th align="left">desc</th></tr></thead><tbody>${rows}</tbody></table>
<p style="font-size:12px;color:#888;margin-top:24px">cron_aftercare_sla_breach - generado ${new Date().toISOString()}</p>
</div>`;

const subject = `[Aftercare SLA breach] ${total} incidentes con plazo vencido`;
return [{ json: { html, subject, total } }];
